"""LTM1: the single durable Part(x, y) store over native symbol handles.

Argument types belong to the concept bank. The relation has no kind column,
predicate slot, vectors, occurrence addresses, or stored reading. Indexes are
rebuilt from the two references after load or compaction.
"""
import math

import torch
from torch import nn


class LTM1(nn.Module):
    columns = ('refs', 'truth_plus', 'truth_minus', 'access_count', 'surprise', 'when')

    def __init__(self, capacity=8192):
        super().__init__()
        self.capacity = int(capacity)
        self.allocate = None
        self.register_buffer('refs', torch.full((self.capacity, 2), -1, dtype=torch.long))
        self.register_buffer('truth_plus', torch.zeros(self.capacity))
        self.register_buffer('truth_minus', torch.zeros(self.capacity))
        self.register_buffer('access_count', torch.zeros(self.capacity, dtype=torch.long))
        self.register_buffer('surprise', torch.full((self.capacity,), -1.))
        self.register_buffer('when', torch.zeros(self.capacity, 4))
        self.register_buffer('count', torch.tensor(0, dtype=torch.long))
        self._index_version = None
        self._pairs, self._parts, self._wholes = {}, {}, {}

    def __len__(self):
        return int(self.count)

    @property
    def revision(self):
        return (id(self.refs), self.refs._version, self.truth_plus._version,
                self.truth_minus._version, self.access_count._version, len(self))

    def _index(self):
        version = (id(self.refs), self.refs._version, len(self))
        if self._index_version == version:
            return
        pairs, parts, wholes = {}, {}, {}
        for row in self.indices().tolist():
            part, whole = self.refs[row].tolist()
            if min(part, whole) <= 0:
                raise ValueError('Part arguments must be positive native symbol handles')
            if (part, whole) in pairs:
                raise ValueError('duplicate Part edge')
            pairs[part, whole] = row
            parts.setdefault(whole, []).append(part)
            wholes.setdefault(part, []).append(whole)
        self._pairs, self._parts, self._wholes = pairs, parts, wholes
        self._index_version = version

    def indices(self):
        return (self.refs[:, 0] > 0).nonzero().flatten()

    def contains(self, symbol):
        return 0 <= int(symbol) < self.capacity and bool((self.refs[int(symbol)] > 0).all())

    def find(self, part, whole):
        self._index()
        return self._pairs.get((int(part), int(whole)))

    def parts(self, whole):
        self._index()
        return tuple(self._parts.get(int(whole), ()))

    def wholes(self, part):
        self._index()
        return tuple(self._wholes.get(int(part), ()))

    @torch.no_grad()
    def add(self, part, whole, *, truth_plus=0., truth_minus=0., when=None,
            surprise=-1., witness=True, symbol=None):
        part, whole = int(part), int(whole)
        if min(part, whole) <= 0:
            raise ValueError('Part arguments must be positive native symbol handles')
        if any(not math.isfinite(float(x)) or not 0 <= float(x) <= 1
               for x in (truth_plus, truth_minus)):
            raise ValueError('Part evidence has two independent poles in [0, 1]')
        if not math.isfinite(float(surprise)):
            raise ValueError('Part surprise must be finite')
        if when is not None:
            when = torch.as_tensor(when, device=self.when.device, dtype=self.when.dtype)
            if when.shape != (4,) or not bool(torch.isfinite(when).all()):
                raise ValueError('Part occurrence time requires four finite coordinates')
        row = self.find(part, whole)
        if row is None:
            if symbol is not None:
                row = int(symbol)
            elif self.allocate is None:
                free = (self.refs[:, 0] < 0).nonzero().flatten()
                free = free[free > 0]
                if not len(free):
                    raise OverflowError('LTM2 capacity exhausted; forgetting is required')
                row = int(free[0])
            else:
                row = int(self.allocate())
            if not 0 < row < self.capacity:
                raise OverflowError('LTM2 symbol index exceeds its capacity')
            if self.contains(row):
                raise RuntimeError('a live Part symbol cannot be reassigned')
            self.refs[row] = self.refs.new_tensor((part, whole))
            self.count += 1
        elif symbol is not None and int(symbol) != row:
            raise ValueError('a Part pair already has a different native symbol')
        self.truth_plus[row] = max(float(self.truth_plus[row]), float(truth_plus))
        self.truth_minus[row] = max(float(self.truth_minus[row]), float(truth_minus))
        self.access_count[row] += int(witness)
        if surprise >= 0:
            self.surprise[row] = float(surprise)
        if when is not None:
            self.when[row].copy_(when)
        return row

    @torch.no_grad()
    def retain(self, indices):
        indices = torch.as_tensor(indices, dtype=torch.long, device=self.refs.device)
        count = len(indices)
        if count and (int(indices.min()) < 0 or int(indices.max()) >= self.capacity
                      or len(indices.unique()) != count
                      or not bool((self.refs[indices] > 0).all())):
            raise ValueError('invalid LTM2 retention selection')
        # Row addresses are native symbol handles. Retention never renumbers
        # them: a retained outer edge must keep the same inner-edge argument.
        erase = torch.ones(self.capacity, dtype=torch.bool, device=self.refs.device)
        erase[indices] = False
        for name in self.columns:
            getattr(self, name)[erase] = -1 if name in ('refs', 'surprise') else 0
        self.count.fill_(count)

    def remove(self, part, whole):
        row = self.find(part, whole)
        if row is not None:
            self.retain([i for i in self.indices().tolist() if i != row])

    def remove_symbol(self, symbol):
        indices = self.indices()
        self.retain(indices[(self.refs[indices] != int(symbol)).all(-1) & (indices != int(symbol))])

    def row(self, index):
        if not self.contains(index):
            raise IndexError('unavailable Part edge')
        return {name: getattr(self, name)[int(index)] for name in self.columns}

    def readings(self, index, types):
        """Permitted readings from argument types; context may choose among them."""
        part, whole = self.refs[int(index)].tolist()
        left, right = set(types(part)), set(types(whole))
        readings = []
        if 'situation' in left and 'situation' in right:
            readings.append('conditional')
        if 'situation' in left and 'speech_individual' in right:
            readings.append('attribution')
        if part != whole and 'object' in left and 'word' in right:
            readings.append('definition')
        if 'kind' in left and 'kind' in right:
            readings.append('subsumption')
        # A form may itself be a singleton. Its DEF edge names an object;
        # that does not make the object identical to the word naming it.
        if 'singleton' in right and 'definition' not in readings:
            readings.append('equality')
        return tuple(readings)

    def _load_from_state_dict(self, state_dict, prefix, *args, **kwargs):
        refs = state_dict.get(prefix + 'refs')
        if refs is not None and refs.shape != self.refs.shape:
            if refs.ndim != 2 or refs.shape[1] != 2:
                raise ValueError('LTM2 requires exactly two symbol references')
            self.capacity = int(refs.shape[0])
            for name in self.columns:
                value = state_dict[prefix + name]
                self._buffers[name] = torch.empty_like(value, device=self.refs.device)
        super()._load_from_state_dict(state_dict, prefix, *args, **kwargs)
        self._index_version = None
        self._index()
        indices = self.indices()
        if len(indices) != len(self):
            raise ValueError('Part count disagrees with its occupied symbol rows')
        values = torch.stack((self.truth_plus[indices], self.truth_minus[indices]))
        if not bool(torch.isfinite(values).all() & (values >= 0).all() & (values <= 1).all()):
            raise ValueError('invalid restored Part evidence')

class ClauseRows:
    """One writer for completed clauses; vector and row readers share its rows."""

    def configure_clause_index(self, *, allocate=None, concept_point, predicate_kind=None, on_part=None, preflight=None):
        object.__setattr__(self, '_allocate_clause_row', allocate)
        object.__setattr__(self, '_concept_point', concept_point)
        object.__setattr__(self, '_predicate_kind', predicate_kind)
        object.__setattr__(self, '_index_part_row', on_part)
        object.__setattr__(self, '_preflight_clause_rows', preflight)

    @torch.no_grad()
    def part_row(self, symbol, *, reading=None):
        """Read an LTM1 edge into a temporary grammatical view.

        Only the two arguments and the six Part columns are durable. The
        grammatical operator in this view is chosen from the argument types.
        """
        symbol = int(symbol)
        part = self.parts.row(symbol)
        owner = self._concept_owner()
        from Spaces import _concept_alloc_of
        alloc = _concept_alloc_of(owner)
        def types(identity):
            result = set(alloc.symbol_types.get(identity, ()))
            if identity in alloc.singletons:
                result.add('singleton')
            if alloc.order_of(identity) > 1:
                result.add('kind')
            return result
        readings = self.parts.readings(symbol, types)
        if reading is None:
            reading = ('implies' if 'conditional' in readings else
                       'equal' if 'equality' in readings else 'part')
        if reading == 'implies' and 'conditional' not in readings:
            raise ValueError('a conditional requires two situation arguments')
        if reading == 'equal' and 'equality' not in readings:
            raise ValueError('equality requires singleton membership')
        left, right = part['refs'].tolist()
        roles = self.slots.new_zeros(3, self.nDim)
        for role, reference in ((0, left), (2, right)):
            value = self._concept_point(reference)
            if value is not None:
                roles[role] = self._fit(value)
        # This is an operation request, not an identity coordinate or a
        # third LTM1 column. It disappears with the read.
        roles[1] = predicate_point(reading, roles[1])
        pair = tuple(float(part[name]) for name in ('truth_plus', 'truth_minus'))
        from ThoughtReferences import with_slots
        meaning = with_slots(ConceptualMeaning(roles,
            torch.ones(3, dtype=torch.bool, device=roles.device),
            role_refs=(('sym', left), ('sym', predicate_identity(reading)), ('sym', right)),
            sentence_kind='relation',
            bindings={'_equality': True} if reading == 'equal' else {}),
            (), pair=pair)
        return dict(part, meaning=meaning, occurrence=('sym', symbol),
            row_id=symbol, refs=part['refs'].clone(), readings=readings,
            evidence=pair, trust=pair[0]-pair[1], source_trust=0.,
            kind='observation' if any(pair) else 'unverified', order=alloc.order_of(symbol),
            stream=(), pending=False,
            metadata_complete=True, expectation=self.expectation_of(('sym', symbol)), text=None)

    def location(self, reference):
        """Find either an LTM0 occurrence or a native LTM1 symbol."""
        if isinstance(reference, tuple):
            if len(reference) == 2 and reference[0] == 'sym' and self.parts.contains(reference[1]):
                return reference
            return self._index_occurrences.get(reference)
        row = self.index_of_row(reference)
        return row if row is not None else (('sym', int(reference))
            if self.parts.contains(reference) else None)

    def clause_relation(self, field):
        """Infer the row kind from occupancy and its REL's native identity."""
        if field.slots.shape[0] == 1:
            return None
        if field.slots.shape[0] != 3:
            raise ValueError('a completed row occupies one or three slots')
        resolve = getattr(self, '_predicate_kind', None)
        reference = field.refs[1]
        if isinstance(reference, ClausePredicate):
            return predicate_relation(reference.identity)
        result = resolve(reference) if resolve is not None and type(reference) is int else 'operator'
        if result not in ('part', 'implies', 'operator'):
            raise ValueError('the REL identity has an unknown grammatical kind')
        return result

    @contextmanager
    def clause_assertions(self, *, trust, origin, text):
        """External TruthSet authority, scoped to completed outer clauses only."""
        previous = self.__dict__.get('_clause_assertion')
        context = dict(trust=float(trust), origin=origin, text=text, rows=[])
        object.__setattr__(self, '_clause_assertion', context)
        try:
            yield context['rows']
        finally:
            object.__setattr__(self, '_clause_assertion', previous)

    def _native_reference_indexes(self):
        """Derived identity-to-occurrence caches, invalidated by row edits."""
        count = len(self)
        token = (count, id(self.row_ids), self.row_ids._version,
                 id(self.refs), self.refs._version)
        if self.__dict__.get('_native_reference_token') != token:
            rows, predicates = {}, {}
            for row, identity in enumerate(self.row_ids[:count].tolist()):
                if identity not in (-1, 0):
                    rows.setdefault(identity, row)
            for row, references in enumerate(self.refs[:count].tolist()):
                for slot, identity in enumerate(references):
                    if (1 << 61) <= identity < (1 << 62):
                        predicates.setdefault(identity, (row, slot))
            object.__setattr__(self, '_native_row_index', rows)
            object.__setattr__(self, '_native_predicate_index', predicates)
            object.__setattr__(self, '_native_reference_token', token)
        return self._native_row_index, self._native_predicate_index

    def index_of_row(self, reference):
        return self._native_reference_indexes()[0].get(int(reference))

    def _index_slot_metadata(self, address):
        from Occurrence import slot_key
        data = dict(self._semantic_rows.get(address, {}).get('bindings', ()))
        for kind, role in (*data.get('_open_references', ()), *data.get('_bound_roles', ())):
            if kind != 'referent':
                continue
            identity = slot_key(address, role)
            previous = self._slot_index.get(identity)
            if previous is not None and previous != (address, role):
                raise RuntimeError('64-bit slot collision; refusing to merge different slots')
            self._slot_index[identity] = address, role

    def slot_of_reference(self, reference):
        """Derived shared posting: source address and role remain authoritative."""
        if self.__dict__.get('_slot_index_source') is not self._semantic_rows:
            self._slot_index_source, self._slot_index = self._semantic_rows, {}
            for address in self._semantic_rows:
                self._index_slot_metadata(address)
        value = self._slot_index.get(int(reference))
        if value is None:
            return None
        address, role = value
        row = self._index_occurrences.get(address)
        if row is None:
            return None
        if self.index_of_row(reference) is not None:
            raise RuntimeError('slot address collides with an occurrence')
        return row, role

    def semantic_reference(self, reference):
        slot = self.slot_of_reference(reference)
        if slot is not None:
            return ('slot', self.occurrence_of(slot[0]), slot[1])
        row = self.index_of_row(reference)
        return self.occurrence_of(row) if row is not None else ('sym', reference)

    def point_of_row(self, reference):
        """Read a concept/idea point; a relation explicitly has no point."""
        slot = self.slot_of_reference(reference)
        if slot is not None:
            return self.slots[slot]
        index = self.index_of_row(reference)
        if index is not None:
            return self.slots[index, 0] if int(self.role_mask[index].sum()) == 1 else None
        occurrence = self._native_reference_indexes()[1].get(int(reference))
        if occurrence is not None:
            return self.slots[occurrence]
        resolve = getattr(self, '_concept_point', None)
        if resolve is None:
            raise ValueError('shared concept index is not attached')
        point = resolve(int(reference))
        if point is None:
            raise ValueError(f'unavailable shared row {reference}')
        return self._fit(point)

    def _clause_reference(self, reference, children):
        if isinstance(reference, ClausePredicate):
            return reference.identity
        return int(self.row_ids[children[reference[1]]]) if isinstance(reference, tuple) else reference

    @torch.no_grad()
    def write_clause(self, clause, *, trust=None, origin=None, stream=-1, kind='observation',
                    evidence=None, text=None, expectation=None, document_key=None,
                    sentence_index=0, content_key=None, written_rows=None):
        """Close concepts into LTM0 and the derivation's argument pairs into LTM1.

        Wide working identities are never stored on occurrence rows. A completed
        relative field returns its native Part symbol; an absolute or still-open
        field returns its occurrence row. Both have the common row/read interface.
        """
        import math
        from PartClosing import PartClosing
        from ThoughtReferences import bindings, open_slots, with_slots
        if not isinstance(clause, Clause):
            raise TypeError('write_clause requires a completed field')
        if document_key is not None:
            from Occurrence import native_content_key
            with self.at_address(document_key, sentence_index,
                                 content_key or native_content_key(clause.meaning)):
                return self.write_clause(clause, trust=trust, origin=origin, stream=stream,
                    kind=kind, evidence=evidence, text=text, expectation=expectation,
                    written_rows=written_rows)
        authority = self.__dict__.get('_clause_assertion')
        if authority is not None:
            if clause.meaning.mode == 'interrogative':
                raise ValueError('a TruthSet cannot assert an interrogative clause')
            trust, origin, text = authority['trust'], authority['origin'], authority['text']
            kind = 'fact'
        if trust is not None and not math.isfinite(float(trust)):
            raise ValueError('clause provenance must be finite')
        if kind not in self.KINDS or type(stream) is not int or stream < -1:
            raise ValueError('invalid clause evidence kind or stream')
        if text is not None and not isinstance(text, str):
            raise ValueError('truth source text must be a string')
        owner = self.__dict__.get('_concept_owner')
        if owner is None or owner() is None:
            raise ValueError('clause admission requires its native concept owner')
        closing = PartClosing(owner(), self)
        context = self.__dict__.get('_write_address')
        nodes, visiting, visited = [], set(), set()
        def visit(value):
            if id(value) in visiting:
                raise ValueError('a temporary derivation cannot contain an object cycle')
            if id(value) in visited:
                return
            visiting.add(id(value))
            for child in value.children:
                visit(child)
            visiting.remove(id(value)); visited.add(id(value)); nodes.append(value)
            for companion in value.companions:
                visit(companion)
        visit(clause)
        pairs, addresses, prepared, required = {}, {}, set(), 0
        prediction = None if expectation is None else expectation.estimate
        surprise = -1. if prediction is None else expectation.surprise_for(clause.meaning)
        sources = () if expectation is None else tuple(expectation.source_occurrences)
        estimate, observation_marks = None, {}
        if prediction is not None:
            if expectation.identities is not None:
                observation_marks['_symbol_handles'] = tuple(expectation.identities.cpu().tolist())
            activation = expectation.activation
            if activation is None:
                activation = expectation.residual + prediction.expected_activation
            observation_marks['_observed_symbol_activations'] = tuple(
                (int(identity), tuple(pair)) for identity, pair in zip(
                    prediction.symbol_ids.cpu().tolist(), activation.detach().cpu().tolist()))
            observation_marks.update({key: value for key, value in bindings(clause.meaning).items()
                                      if key == '_withheld_symbols'})
            if sources:
                if any(self.location(source) is None for source in sources):
                    raise ValueError('estimate source occurrence is unavailable')
                retained = prediction.retained_bindings(observed=expectation.observed,
                    occupied=expectation.occupied, activation=activation,
                    identities=expectation.identities)
                # The predictor's frozen activation target is an audit of
                # the arrival, not another stored working identity or an
                # extra column on a Part edge.
                retained['_expectation_observation'] = observation_marks
                estimate = ConceptualMeaning(prediction.roles,
                    torch.ones(3, dtype=torch.bool, device=prediction.roles.device),
                    mode='unspecified', bindings=retained, scope=prediction.scope)
                self._validate_local_references(estimate)
                self._normalise_expectation_provenance(dict(kind='estimate',
                    source_occurrences=sources, intended_occurrence=None,
                    presence_logits=tuple(prediction.presence_logits.detach().cpu().tolist()),
                    stream=expectation.stream, document=expectation.document), self.address_domain)
                previous = self._address_for_write(estimate, kind='estimate',
                    **self._estimate_write_address(estimate, document=expectation.document,
                                                  stream=expectation.stream))[-1]
                required += previous is None
        def pending(value):
            return any(tag != 'evidence' for tag, _ in
                bindings(value.meaning).get('_open_references', ())) or (value.relation is not None
                and any(value.refs[role] in (-1, 0) for role in (0, 2)))
        def incomplete(value):
            return pending(value) or any(incomplete(child) for child in value.children)
        def retained_pair(value):
            term = closing._terms.get(id(value))
            return (value.relation is not None and term is not None
                and closing._planned[id(term)]['edge'] is not None)
        for position, value in enumerate(nodes):
            asserted = value is clause or value in clause.companions
            pair = tuple(map(float, value.evidence if evidence is None or not asserted else evidence))
            if asserted and (authority is not None or (trust is not None and evidence is None)):
                signed = max(-1., min(1., float(trust)))
                pair = (max(signed, 0.), max(-signed, 0.))
                if not value.meaning.polarity:
                    pair = pair[::-1]
            if len(pair) != 2 or any(not math.isfinite(x) or not 0 <= x <= 1 for x in pair):
                raise ValueError('clause evidence requires two finite poles in [0, 1]')
            pairs[id(value)] = pair
            if not incomplete(value):
                closing.prepare(value)
                prepared.add(id(value))
            if retained_pair(value):
                continue
            from Occurrence import native_content_key
            kwargs = ({} if value is clause and context is not None else
                dict(document_key=('direct', kind) if context is None else
                     ('embedded', context[0], context[1]), sentence_index=position,
                     content_key=native_content_key(value.meaning)))
            previous = self._address_for_write(value.meaning,
                kind=kind if asserted else 'unverified', **kwargs)[-1]
            required += previous is None
            addresses[id(value)] = kwargs
        if len(self) + required > self.capacity:
            raise OverflowError('LTM1 capacity exhausted before clause admission')
        closing.preflight()
        from RowTime import stamp
        closing.when = stamp(self)
        rows = {}
        estimate_index = None
        if estimate is not None:
            estimate_index = self.append_estimate(estimate,
                presence_logits=prediction.presence_logits, source_occurrences=sources,
                stream=expectation.stream, document=expectation.document)
        for value in nodes:
            asserted = value is clause or value in clause.companions
            pair = pairs[id(value)]
            if id(value) in prepared:
                symbol = closing.close(value, pair=pair, when=closing.when,
                                       surprise=surprise if asserted else -1.)
            else:
                symbol = None
            if retained_pair(value):
                if symbol is None or not self.parts.contains(symbol):
                    raise RuntimeError('a completed relation did not produce a Part edge')
                rows[id(value)] = ('sym', symbol)
                continue
            retain_open = pending(value) or (value.relation is not None and incomplete(value))
            if retain_open:
                # An open question is retained at the existing occurrence
                # boundary. Filling it later changes only its working read.
                named = []
                for role, reference in enumerate(value.refs):
                    if isinstance(reference, ClausePredicate):
                        reference = ('sym', reference.identity)
                    elif isinstance(reference, tuple) and reference[:1] == ('clause',):
                        child = value.children[reference[1]]
                        term = closing._terms.get(id(child))
                        symbol = None if term is None else closing.symbols.get(id(term))
                        reference = (('sym', symbol) if symbol is not None
                            and closing._point(symbol) is not None else
                            self.occurrence_of(rows[id(child)]))
                    elif type(reference) is int and reference not in (-1, 0):
                        reference = self.semantic_reference(reference)
                    else:
                        reference = value.meaning.role_refs[role]
                    named.append(reference)
                stored = replace(value.meaning, role_refs=tuple(named))
            else:
                point = value.point
                if point is None:
                    point = closing._terms[id(value)].point
                stored = ConceptualMeaning.from_description(self._fit(point))
                if symbol is not None:
                    # This is the address of the surviving derivation, not
                    # the dissolved working identity. Membership reads the
                    # Part arguments; it never inverts this narrowed point.
                    stored = replace(stored, role_refs=(('sym', symbol), None, None))
            marks = bindings(value.meaning)
            retained = {key: marks[key] for key in ('_withheld_symbols',) if key in marks}
            if retain_open:
                retained.update(marks)
            if value is clause:
                retained.update(observation_marks)
            stored = with_slots(replace(stored, mode=value.meaning.mode,
                sentence_kind=stored.sentence_kind if retain_open else 'idea',
                bindings=retained), open_slots(stored), pair=pair)
            before_count = len(self)
            row = self.append_meaning(stored, kind=kind if asserted else 'unverified',
                trust=0. if trust is None or not asserted else float(trust), stream=stream,
                surprise=surprise if asserted else -1., evidence=pair, order=value.order,
                **addresses[id(value)])
            if row >= before_count:
                self.when[row].copy_(closing.when)
            if origin is not None:
                self.set_origin(row, origin, text=text if asserted else None)
            rows[id(value)] = row
        result = rows[id(clause)]
        if estimate_index is not None:
            self.link_estimate_observation(estimate_index, result)
        if written_rows is not None:
            written_rows.update(rows)
            written_rows.update({('symbol', id(value)):
                closing.symbols.get(id(closing._terms.get(id(value))))
                for value in nodes})
            written_rows[('symbols', id(clause))] = tuple(dict.fromkeys(
                symbol for symbol in closing.symbols.values()
                if symbol in closing.alloc.individuals))
            written_rows[('activations', id(clause))] = tuple(
                (self.occurrence_of(rows[id(value)]),
                 symbol if symbol in closing.alloc.individuals else None,
                 (value.reference_request or {}).get('role', 0))
                for value in nodes if value.order == 1
                for symbol in (written_rows.get(('symbol', id(value))),))
        if authority is not None:
            authority['rows'].append(result)
        return result

    def _update_forward_index(self, address):
        """Maintain the shared, derived posting list for unresolved identities."""
        if self.__dict__.get('_slot_index_source') is self._semantic_rows:
            self._index_slot_metadata(address)
        if self.__dict__.get('_forward_index_source') is not self._semantic_rows:
            return  # A restored/replaced store is rebuilt on its next lookup.
        postings = self._forward_postings
        by_address = self._forward_by_address
        for identity in by_address.pop(address, ()):
            postings[identity].discard(address)
            if not postings[identity]:
                del postings[identity]
        metadata = self._semantic_rows.get(address, {})
        identities = {identity for _, identity in
                      dict(metadata.get('bindings', ())).get('_forward_references', ())}
        if identities:
            by_address[address] = identities
            for identity in identities:
                postings.setdefault(identity, set()).add(address)

    def _forward_addresses(self, identities):
        if self.__dict__.get('_forward_index_source') is not self._semantic_rows:
            self._forward_index_source = self._semantic_rows
            self._forward_postings, self._forward_by_address = {}, {}
            for address in self._semantic_rows:
                self._update_forward_index(address)
        return set().union(*(self._forward_postings.get(identity, ()) for identity in identities))

    def read_reference_bindings(self, index, meaning, *, exclude=()):
        """Read an already bound token; equality rows never select a binding.

        The journal's pending names and structural constituent references stay
        immutable. Only ReferenceClose.commit can refine their MTM token.
        """
        from ThoughtReferences import bindings, fill, open_slots, with_slots
        owner_ref = self.__dict__.get('_concept_owner')
        owner = None if owner_ref is None else owner_ref()
        if owner is None or not isinstance(index, int):
            return meaning
        resolver, mtm = owner.components.reference_close, owner.mtm
        occurrence = self.occurrence_of(index)
        for role, _name in bindings(meaning).get('_forward_references', ()):
            reference = meaning.role_refs[role]
            site = reference if reference is not None and reference[0] == 'ltm' else occurrence
            token = mtm.token_of(site)
            if token is None:
                kind = resolver._derivation_symbol(reference)
                if kind is None:
                    continue
                point = self._concept_point(kind)
                target, uses = reference, (site,)
            else:
                kind = mtm.entries[token].kind
                point = None if kind is None else resolver.token_value(token)
                # A token's own one-slot read exposes its derivation,
                # terminating the address walk. A parent keeps its token.
                target = ('sym', kind) if site == occurrence else token
                uses = mtm.entries[token].occurrences
            # The retained parent already points at its anonymous child. That
            # structural pointer is not the pending role's bound content.
            references = list(meaning.role_refs)
            references[role] = None
            meaning = with_slots(replace(meaning, role_refs=tuple(references)),
                                 (*open_slots(meaning), ('referent', role)))
            if point is None:
                continue
            witnesses = [self.location(address) for address in uses]
            witnesses = [row for row in witnesses if isinstance(row, int)]
            meaning = fill(meaning, dict(reference=target, binding_value=point,
                support_true=max(float(self.c_plus[row]) for row in witnesses),
                support_false=max(float(self.c_minus[row]) for row in witnesses)), slots=(('referent', role),),

def forget_parts(parts, config, *, retained=()):
    """Retention over the same six columns for taxonomy and definitions."""
    if len(parts) < math.ceil(config.high_water * parts.capacity):
        return None
    from RowTime import encoder
    rows = parts.indices().tolist()
    target = math.floor(config.low_water * parts.capacity)
    ticks = encoder().decode_index(parts.when[rows])
    known = parts.when[rows].ne(0).any(-1)
    tail = int(ticks[known].max()) if bool(known.any()) else 0
    ages = {row: max(0, tail-int(ticks[i])) if bool(known[i]) else 0 for i, row in enumerate(rows)}
    proofs = part_supports(parts)
    protected = {int(ref[1]) for ref in retained if ref[:1] == ('sym',) and parts.contains(ref[1])}
    alive = set(rows)
    def value(row):
        utility = 1. if float(parts.surprise[row]) < 0 else float(parts.surprise[row])
        if any(proof <= alive for proof in proofs.get(row, ())):
            utility = 0.
        access = math.log1p(int(parts.access_count[row]))
        truth = max(float(parts.truth_plus[row]), float(parts.truth_minus[row]))
        return (config.trust_weight*truth + config.utility_weight*utility
                + config.luminosity_weight*access - config.age_weight*(-math.expm1(-ages[row]/config.half_life)))
    for row in sorted(rows, key=lambda row: (value(row), -ages[row], row)):
        if len(alive) <= target:
            break
        if row in protected:
            continue
        available = next((proof for proof in proofs.get(row, ()) if proof <= alive-{row}), None)
        if available is not None:
            protected.update(available)
        alive.remove(row)
    parts.retain(sorted(alive))
    return dict(before=len(rows), after=len(alive), target=target, protected=len(protected),
                target_reached=len(alive) <= target)


def retention_values(store, config, *, alive=None, supports=None):
    """Return independent retention terms; no stored evidence is changed."""
    n = len(store)
    alive = set(range(n)) if alive is None else alive
    supports = {} if supports is None else supports
    trust = store.source_trust[:n].abs()
    utility = torch.where(store.surprise[:n] < 0, 1., store.surprise[:n]).clamp(0, 1)
    for row, choices in supports.items():
        if any(witnesses <= alive for witnesses in choices):
            utility[row] = 0.
    luminosity = torch.ones_like(trust)
    positive, negative = store.c_plus[:n], store.c_minus[:n]
    # Intrinsic both is heterogeneous content, not two disagreeing sources.
    signs = (positive.gt(0) & negative.eq(0)).long() - (negative.gt(0) & positive.eq(0)).long()
    points = F.normalize(store.slots[:n, 0], dim=-1)
    refs = store.refs[:n]
    orders = store.order[:n]
    scopes = _scope_keys(store)
    scope_ids = {key: i for i, key in enumerate(dict.fromkeys(scopes))}
    scope = torch.tensor([scope_ids[key] for key in scopes], device=trust.device)
    live = torch.tensor([i in alive for i in range(n)], device=trust.device)
    for start in range(0, n, 128):
        end = min(n, start + 128)
        same = points[start:end] @ points.T > config.similarity
        same &= orders[start:end, None] == orders[None]
        same &= scope[start:end, None] == scope[None]
        contrary = signs[start:end, None] * signs[None] == -1
        weaker = trust[start:end, None] < trust[None]
        luminosity[start:end] = (~(same & contrary & weaker & live[None]).any(-1)).to(trust)
    if config.coverage:
        # Catuskoti coverage over occupied idea coordinates. Opposite poles
        # stay separate; leave-one-out measures the lost positive coverage.
        ids = [i for i in sorted(alive) if int(store.role_mask[i].sum()) == 1]
        if ids:
            codes = store.slots[ids, 0].abs().clamp(0, 1)
            for_pole = codes * positive[ids, None]
            against_pole = codes * negative[ids, None]
            def coverage(p, q):
                if not len(p):
                    return codes.new_zeros(())
                a, b = p.amax(0), q.amax(0)
                return (a - b - torch.minimum(a, b)).mean()
            full = coverage(for_pole, against_pole)
            for local, row in enumerate(ids):
                keep = torch.arange(len(ids), device=codes.device) != local
                luminosity[row] = (full - coverage(for_pole[keep], against_pole[keep])).clamp(0, 1)
    age = history_age(store)
    penalty = -torch.expm1(-age / config.half_life)
    value = (config.trust_weight * trust + config.utility_weight * utility
             + config.luminosity_weight * luminosity - config.age_weight * penalty)
    return dict(value=value, trust=trust, utility=utility, luminosity=luminosity, age=age)


def _references(store, row, context, rows):
    result = set()
    for ref in store._context_occurrence_references(context):
        if ref[:2] == ('ltm', store.address_domain):
            if ref[2] not in rows:
                raise ValueError('forgetting found an unavailable semantic occurrence')
            result.add(rows[ref[2]])
    for ref in store.refs[row].tolist():
        if ref in rows:
            result.add(rows[ref])
    return result


def _trim_expectations(store, alive):
    records = copy.deepcopy(store._expectation_rows)
    def retained(reference):
        return (store.parts.contains(reference[1]) if reference[0] == 'sym'
                else reference[2] in alive)
    for key in list(records):
        if key not in alive:
            del records[key]
            continue
        value = records[key]
        if value['kind'] == 'estimate':
            value['source_occurrences'] = tuple(ref for ref in value['source_occurrences'] if retained(ref))
            target = value['intended_occurrence']
            if target is not None and not retained(target):
                value['intended_occurrence'] = None
        else:
            refs = [ref for ref in (value['estimate_occurrence'], *value.get('previous_estimates', ()))
                    if ref[2] in alive]
            if not refs:
                del records[key]
            else:
                value['estimate_occurrence'] = refs[0]
                value['previous_estimates'] = tuple(refs[1:])
    return records


@torch.no_grad()
def forget(store, config=None, *, document_boundary=False, epoch_boundary=False,
           open_sentence=False, stateless=False, retained_occurrences=()):
    """Plan a complete deletion/coarsening transaction before publishing it."""
    config = config or ForgettingConfig()
    n = len(store)
    if (not config.enabled or stateless or open_sentence or torch.compiler.is_compiling()
            or not (document_boundary or epoch_boundary)):
        return None
    pressure = n >= math.ceil(config.high_water * store.capacity)
    if not pressure and not (epoch_boundary and config.at_epoch):
        return None
    if int(store.forget_passes) and int(store.forget_sentences - store.forget_last_sentence) < config.min_interval:
        return None
    target = math.floor(config.low_water * store.capacity)
    if n <= target:
        return None
    keys = list(map(int, store.address_keys[:n].tolist()))
    indexes = {key: i for i, key in enumerate(keys)}
    contexts = {key: copy.deepcopy(store._semantic_rows.get(key, {})) for key in keys}
    store._validate_constituent_graph(contexts, store.address_domain)
    store._validate_expectation_links()
    if any(store.meaning_of(i) is None for i in range(n)):
        raise ValueError('forgetting requires the complete semantic sidecar')
    dependencies = {i: _references(store, i, contexts[key], indexes) for i, key in enumerate(keys)}
    protected = {i for i in range(n) if int(store.origin[i]) in config.protect_origins}
    for ref in retained_occurrences:
        if ref[:1] == ('sym',) and store.parts.contains(ref[1]):
            continue
        if ref[:2] != ('ltm', store.address_domain) or ref[2] not in indexes:
            raise ValueError('forgetting live root is unavailable')
        protected.add(indexes[ref[2]])
    pending = list(protected)
    while pending:
        for child in dependencies[pending.pop()]:
            if child not in protected:
                protected.add(child)
                pending.append(child)
    supports = {}
    terms = retention_values(store, config, supports=supports)
    order = sorted(range(n), key=lambda i: (float(terms['value'][i]), -float(terms['age'][i]), keys[i]))
    alive, advanced, changed, coarsened = set(range(n)), set(), set(), set()
    refs = store.refs[:n].clone()
    store._ensure_texts(n)
    texts = list(store._texts[:n])
    dropped_text = cascade = 0
    cutoff = None
    if len(protected) <= target:
        # A row takes at most one detail stage per pass. Text removal frees
        # sidecar memory, not seats; later passes may coarsen or delete it.
        for row in order:
            if row not in protected and texts[row] is not None:
                texts[row] = None
                advanced.add(row)
                changed.add(row)
                dropped_text += 1

        def deletion(row):
            removed, edits = {row}, {}
            while True:
                previous = set(removed)
                for parent in alive - removed:
                    lost = dependencies[parent] & removed
                    if not lost:
                        continue
                    context = copy.deepcopy(contexts[keys[parent]])
                    roles = list(context.get('role_refs', (None, None, None)))
                    new_refs = refs[parent].clone()
                    coarse = set()
                    for role in range(3):
                        child = indexes.get(int(refs[parent, role]))
                        ref = roles[role]
                        if ref is not None and ref[:2] == ('ltm', store.address_domain):
                            child = indexes[ref[2]]
                        if child in lost and int(store.role_mask[child].sum()) == 1 and bool(store.role_mask[parent, role]):
                            roles[role], new_refs[role] = None, -1
                            coarse.add(child)
                    context['role_refs'] = tuple(roles)
                    remaining = {indexes[ref[2]] for ref in store._context_occurrence_references(context)
                                 if ref[:2] == ('ltm', store.address_domain)}
                    if lost - coarse or remaining & lost:
                        removed.add(parent)
                    else:
                        edits[parent] = context, new_refs
                if removed & (protected | advanced):
                    return None
                if removed == previous:
                    break
            edits = {i: value for i, value in edits.items() if i not in removed}
            if set(edits) & (protected | advanced):
                return None
            return removed, edits

        subordinate = set().union(*dependencies.values()) if dependencies else set()
        stages = ([i for i in order if i in subordinate and int(store.record_kind[i]) == store.KINDS.index('unverified')], order)
        for candidates in stages:
            queue = [(float(terms['value'][i]), -float(terms['age'][i]), keys[i], i) for i in candidates]
            heapq.heapify(queue)
            while queue:
                if len(alive) <= target:
                    break
                value, age, key, row = heapq.heappop(queue)
                if row not in alive or row in protected or row in advanced:
                    continue
                if row in supports and not any(proof <= alive - coarsened for proof in supports[row]):
                    corrected = float(terms['value'][row]) + config.utility_weight * (1. - float(terms['utility'][row]))
                    if corrected > value:
                        heapq.heappush(queue, (corrected, age, key, row))
                        continue
                result = deletion(row)
                if result is None:
                    continue
                removed, edits = result
                # If deducibility made a row expendable, retain a complete
                # proof in the surviving set for the remainder of this pass.
                witnesses = set()
                for item in removed:
                    choices = [proof for proof in supports.get(item, ()) if proof <= alive - coarsened]
                    if choices:
                        available = next((proof for proof in choices if not proof & removed), None)
                        if available is None:
                            break
                        witnesses.update(available)
                else:
                    alive -= removed
                    protected.update(witnesses)
                    cascade += len(removed) - 1
                    cutoff = value
                    for parent, (context, reference) in edits.items():
                        contexts[keys[parent]], refs[parent] = context, reference
                        dependencies[parent] -= removed
                        changed.add(parent)
                        coarsened.add(parent)
                        advanced.add(parent)
                    continue
                # A selected group would remove its own derivation.

    keep = sorted(alive)
    kept_keys = {keys[i] for i in keep}
    contexts = {key: value for key, value in contexts.items() if key in kept_keys}
    store._validate_constituent_graph(contexts, store.address_domain)
    expectations = _trim_expectations(store, kept_keys)
    store._validate_expectation_links(expectations)
    removed = set(range(n)) - alive
    by_origin = {origin: sum(int(store.origin[i]) == origin for i in removed) for origin in (0, 1, 2)}
    store._semantic_rows = contexts
    store._expectation_rows = expectations
    store.refs[:n].copy_(refs)
    store._texts[:n] = texts
    store.compact_rows(keep)
    for row in range(len(store)):
        context = store._semantic_rows.get(int(store.address_keys[row]), {})
        store.metadata_required[row] = bool(context.get('bindings') or context.get('scope') or
            any(ref is not None for ref in context.get('role_refs', ()))) or (
            store.text_of(row) is not None or int(store.address_keys[row]) in expectations)
        store._update_semantic_fingerprint(row)
    for old in coarsened & alive:
        row = store.index_of_row(keys[old])
        store._drop_row_postings(row)
        meaning = store.meaning_of(row)
        terms_for_row, complete = store._meaning_leaf_terms(meaning, order=int(store.order[row]))
        store._append_leaf_terms(row, terms_for_row, complete)
    store.forget_passes.add_(1)
    store.forget_last_sentence.copy_(store.forget_sentences)
    store.forget_cutoff.fill_(0. if cutoff is None else cutoff)
    report = dict(before=n, after=len(store), target=target, cutoff=cutoff, deleted_by_origin=by_origin,
                  cascade=cascade, wording=dropped_text, coarsened=len(coarsened),
                  protected=len(protected), target_reached=len(store) <= target)
    store.last_forgetting_report = report
    from util import TheMessage
    TheMessage(f'[LTM forgetting] {report}')
    if not report['target_reached']:
        warnings.warn('LTM forgetting could not reach low water without violating protection or gradual detail loss',
                      RuntimeWarning, stacklevel=2)
    return report


def _live_occurrences(value, namespace):
    pending, found, seen = [value], set(), set()
    while pending:
        item = pending.pop()
        if id(item) in seen:
            continue
        seen.add(id(item))
        if is_dataclass(item) and not isinstance(item, type):
            pending.extend(getattr(item, field.name) for field in fields(item))
        elif isinstance(item, dict):
            pending.extend(item.values())
        elif isinstance(item, (list, tuple)):
            if (len(item) == 3 and isinstance(item[0], str) and item[0] == 'ltm'
                    and isinstance(item[1], str) and item[1] == namespace and type(item[2]) is int):
                found.add(tuple(item))
            else:
                pending.extend(item)
    return found


